package com.lifeorganizer;

import javafx.geometry.*;import javafx.scene.control.*;import javafx.scene.layout.*;import java.sql.*;import java.time.*;import java.time.format.DateTimeFormatter;import java.util.*;

public class CalendarView extends BorderPane {
 private final int userId; private YearMonth month=YearMonth.now(); private final GridPane days=new GridPane(); private final Label heading=new Label(); private final TextArea details=new TextArea();
 public CalendarView(int userId){this.userId=userId;setPadding(new Insets(18));setStyle("-fx-background-color:#f4f6f8;");
  Button prev=new Button("‹ Previous"),next=new Button("Next ›"),today=new Button("Today"),add=new Button("Add event"),refresh=new Button("Refresh");
  prev.setOnAction(e->{month=month.minusMonths(1);render();});next.setOnAction(e->{month=month.plusMonths(1);render();});today.setOnAction(e->{month=YearMonth.now();render();});add.setOnAction(e->addEvent());refresh.setOnAction(e->render());
  heading.setStyle("-fx-font-size:22px;-fx-font-weight:bold;-fx-text-fill:#17324d;");HBox bar=new HBox(9,prev,today,next,heading,add,refresh);bar.setAlignment(Pos.CENTER_LEFT);
  days.setHgap(5);days.setVgap(5);String[] names={"Mon","Tue","Wed","Thu","Fri","Sat","Sun"};for(int i=0;i<7;i++){Label l=new Label(names[i]);l.setMaxWidth(Double.MAX_VALUE);l.setAlignment(Pos.CENTER);l.setStyle("-fx-font-weight:bold;-fx-padding:8;-fx-background-color:#dfe7ee;");days.add(l,i,0);}
  details.setEditable(false);details.setPrefRowCount(5);VBox box=new VBox(10,bar,days,new Label("Selected date events"),details);setCenter(box);render();
 }
 private void render(){heading.setText(month.getMonth()+" "+month.getYear());days.getChildren().removeIf(n->GridPane.getRowIndex(n)!=null&&GridPane.getRowIndex(n)>0);
  LocalDate first=month.atDay(1);int offset=first.getDayOfWeek().getValue()-1;
  for(int d=1;d<=month.lengthOfMonth();d++){LocalDate date=month.atDay(d);VBox cell=new VBox(3);cell.setPadding(new Insets(6));cell.setMinSize(95,76);cell.setStyle("-fx-background-color:white;-fx-border-color:#d8e0e7;");Label num=new Label(String.valueOf(d));num.setStyle("-fx-font-weight:bold;");Label count=new Label(eventSummary(date));count.setWrapText(true);count.setStyle("-fx-font-size:10px;-fx-text-fill:#52677a;");cell.getChildren().addAll(num,count);cell.setOnMouseClicked(e->showDate(date));days.add(cell,(offset+d-1)%7,1+(offset+d-1)/7);}
 }
 private String eventSummary(LocalDate date){try(Connection c=Db.connect();PreparedStatement p=c.prepareStatement("SELECT COUNT(*) FROM calendar_events WHERE user_id=? AND event_date=?")){p.setInt(1,userId);p.setDate(2,java.sql.Date.valueOf(date));try(ResultSet r=p.executeQuery()){return r.next()&&r.getInt(1)>0?r.getInt(1)+" event(s)":"";}}catch(Exception e){return "";}}
 private void showDate(LocalDate date){StringBuilder b=new StringBuilder(date.format(DateTimeFormatter.ofPattern("EEEE, d MMMM yyyy"))+"\n\n");try(Connection c=Db.connect();PreparedStatement p=c.prepareStatement("SELECT event_id,event_title,event_time,description FROM calendar_events WHERE user_id=? AND event_date=? ORDER BY event_time")){p.setInt(1,userId);p.setDate(2,java.sql.Date.valueOf(date));try(ResultSet r=p.executeQuery()){while(r.next())b.append("#").append(r.getInt(1)).append("  ").append(Objects.toString(r.getString(3),"All day")).append("  ").append(r.getString(2)).append("\n").append(Objects.toString(r.getString(4),"")).append("\n\n");}}catch(Exception e){b.append(e.getMessage());}details.setText(b.toString());}
 private void addEvent(){Dialog<ButtonType>d=new Dialog<>();d.setTitle("Add calendar event");ButtonType save=new ButtonType("Save",ButtonBar.ButtonData.OK_DONE);d.getDialogPane().getButtonTypes().addAll(save,ButtonType.CANCEL);GridPane g=new GridPane();g.setHgap(8);g.setVgap(8);g.setPadding(new Insets(12));TextField title=new TextField(),date=new TextField(LocalDate.now().toString()),time=new TextField("09:00:00"),desc=new TextField(),rem=new TextField("0");g.addRow(0,new Label("Title"),title);g.addRow(1,new Label("Date YYYY-MM-DD"),date);g.addRow(2,new Label("Time HH:MM:SS"),time);g.addRow(3,new Label("Description"),desc);g.addRow(4,new Label("Reminder minutes before"),rem);d.getDialogPane().setContent(g);d.showAndWait().ifPresent(bt->{if(bt==save)try(Connection c=Db.connect();PreparedStatement p=c.prepareStatement("INSERT INTO calendar_events(user_id,event_title,event_date,event_time,description,reminder_minutes) VALUES(?,?,?,?,?,?)")){p.setInt(1,userId);p.setString(2,title.getText().trim());p.setDate(3,java.sql.Date.valueOf(date.getText().trim()));p.setTime(4,Time.valueOf(time.getText().trim()));p.setString(5,desc.getText());p.setInt(6,Integer.parseInt(rem.getText()));if(title.getText().isBlank())throw new IllegalArgumentException("Title is required");p.executeUpdate();render();showDate(LocalDate.parse(date.getText().trim()));}catch(Exception ex){new Alert(Alert.AlertType.ERROR,"Could not save event: "+ex.getMessage()).showAndWait();}});}
}
